APPEARANCE=r'\b(?:red|blue|green|yellow|black|white|pink|purple|brown|gray|grey|blond|blonde|bald|striped|stripy|checkered|checked|floral|long-haired|short-haired|white-haired|black-haired|young|old|elderly|little|tall|short|fat|thin|slim|small|large|big|shirt|shirts|t-shirt|tshirt|suit|suits|coat|jacket|dress|skirt|pants|trousers|jeans|shorts|sleeves|hat|cap|helmet|glasses|sunglasses|uniform|clothes|clothing|gown|wearing|dressed|hair|beard|mustache|fur|furry|spotted)\b'
